package com.metaplatform.agent.action;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant;
@Entity @Table(name="action_proposals") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class ActionProposalEntity { @Id @Column(name="proposal_id",length=64) private String proposalId; @Column(name="run_id",nullable=false,length=64) private String runId;
    @Column(name="tenant_id",length=64) private String tenantId; @Column(name="task_id",length=64) private String taskId; @Column(name="action_code",nullable=false,length=128) private String actionCode; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(name="target_objects",nullable=false,columnDefinition="jsonb") private String targetObjects; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String parameters; @Column(nullable=false,columnDefinition="jsonb") private String reason; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(name="evidence_refs",nullable=false,columnDefinition="jsonb") private String evidenceRefs; @Enumerated(EnumType.STRING) @Column(name="risk_level",nullable=false,length=16) private RiskLevel riskLevel; @Column(name="approval_required",nullable=false) private boolean approvalRequired; @Column(name="idempotency_key",nullable=false,unique=true,length=128) private String idempotencyKey; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private ActionProposalStatus status; @Column(name="decided_by",length=128) private String decidedBy; @Column(name="decision_at") private Instant decisionAt; @Column(name="decision_reason",columnDefinition="jsonb") private String decisionReason; @Column(name="proposed_at",nullable=false) private Instant proposedAt; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }

